DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT119-S4-Q20$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S4-Q20'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT119-S4-Q20$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$We can make a car that is both fuel efficient and crash safe.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$We can make a car twice as efficient. We can make a car that meets crash standards.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Each feature is possible alone. That doesn't mean both are possible together. The features might conflict.$batch12$), (3, $batch12$Goal$batch12$, $batch12$A is possible and B is possible, so A and B together are possible.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT119-S4-Q20$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
